package com.example

/**
 * Curated, 100% syllabus-accurate, non-repeating Flashcard Data
 * for Science (විද්‍යාව) and Mathematics (ගණිතය) across Grades 9, 10, and 11.
 * Strictly guarantees that Grade 9, Grade 10, and Grade 11 have distinct curriculum-aligned questions
 * and each set contains 20 completely unique, 100% accurate questions and answers.
 */
object FlashcardSetsScienceMaths {

  fun getScienceCard(setNum: Int, cardNum: Int, grade: String, theme: String): CardContentTuple {
    val c = cardNum.coerceIn(1, 20)
    return when (grade) {
      "11" -> when (setNum) {
        1 -> getGrade11ScienceSet1(c) // ප්‍රභාසංස්ලේෂණය & ආහාර නිෂ්පාදනය
        2 -> getGrade11ScienceSet2(c) // සෛලීය ශ්වසනය & ATP
        3 -> getGrade11ScienceSet3(c) // ප්‍රවේණිය, DNA & මෙන්ඩල් නියම
        4 -> getGrade11ScienceSet4(c) // ධාරා විද්‍යුතය & ඕම් නියමය
        else -> getScienceSet10General(setNum, c, theme)
      }
      "9" -> when (setNum) {
        1 -> getGrade9ScienceSet1(c) // ජීවීන්ගේ විවිධත්වය & සෛලය
        2 -> getGrade9ScienceSet2(c) // පදාර්ථයේ ව්‍යුහය & මූලද්‍රව්‍ය
        3 -> getGrade9ScienceSet3(c) // ශක්ති ප්‍රභව & තාපය
        4 -> getGrade9ScienceSet4(c) // ශාක හා සත්ත්ව පටක
        else -> getScienceSet10General(setNum, c, theme)
      }
      else -> when (setNum) { // Grade 10
        1 -> getScienceSet1(c) // ජීවයේ රසායනික පදනම (Biomolecules)
        2 -> getScienceSet2(c) // පදාර්ථයේ ව්‍යුහය & ආවර්තිතා වගුව
        3 -> getScienceSet3(c) // සෛලය & පටක (Cell & Tissues)
        4 -> getScienceSet4(c) // චලිතය, නිව්ටන් නියම & බලය
        else -> getScienceSet10General(setNum, c, theme)
      }
    }
  }

  fun getMathCard(setNum: Int, cardNum: Int, grade: String, theme: String): CardContentTuple {
    val c = cardNum.coerceIn(1, 20)
    return when (grade) {
      "11" -> when (setNum) {
        1 -> getGrade11MathSet1(c) // සැබෑ ලඝුගණක & ගණනය
        2 -> getGrade11MathSet2(c) // සරල පොලිය & අඩු වන ශේෂ ක්‍රමය
        3 -> getGrade11MathSet3(c) // වර්ගජ සමීකරණ & සූත්‍ර ක්‍රමය
        else -> getMathSetGeneral(setNum, c, theme)
      }
      "9" -> when (setNum) {
        1 -> getGrade9MathSet1(c) // සංඛ්‍යා රටා & ගුණාකාර
        2 -> getGrade9MathSet2(c) // භාග & දශම එකතු කිරීම
        3 -> getGrade9MathSet3(c) // මූලික වීජ ගණිතය & ප්‍රකාශන
        else -> getMathSetGeneral(setNum, c, theme)
      }
      else -> when (setNum) { // Grade 10
        1 -> getMathSet1(c) // වීජීය ප්‍රකාශන, සාධක & සුළු කිරීම්
        2 -> getMathSet2(c) // වර්ග දෙකක අන්තරය & පූර්ණ වර්ග
        3 -> getMathSet3(c) // සමාන්තර ශ්‍රේඪි & n වන පදය
        else -> getMathSetGeneral(setNum, c, theme)
      }
    }
  }

  // ==============================================================================
  // GRADE 11 SCIENCE SETS (20 Cards Each - 100% Unique & Syllabus-Accurate)
  // ==============================================================================

  // Grade 11 Science Set 1: ප්‍රභාසංස්ලේෂණය & ආහාර නිෂ්පාදනය
  private fun getGrade11ScienceSet1(c: Int): CardContentTuple {
    val items = listOf(
      CardContentTuple("ප්‍රභාසංස්ලේෂණයේ සමස්ත තුලිත රසායනික සමීකරණය ලියන්න.", "6CO₂ + 6H₂O + ආලෝක ශක්තිය (ක්ලෝරොෆිල් හමුවේ) → C₆H₁₂O₆ + 6O₂", "ප්‍රභාසංස්ලේෂණය යනු ඇනබොලික් (සංස්ලේෂී) ක්‍රියාවලියකි.", "6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂"),
      CardContentTuple("ප්‍රභාසංස්ලේෂණයේ ප්‍රධාන අදියර 2 මොනවාද? ඒවා සිදුවන ස්ථාන මොනවාද?", "1. ආලෝක අදියර: හරිතලවයේ තයිලකොයිඩ (ග්‍රානා) පටල මත. 2. අඳුරු අදියර (කැල්වින් චක්‍රය): හරිතලවයේ ස්ට්‍රෝමාව තුළ.", "ආලෝක අදියරට හිරු එළිය අත්‍යවශ්‍ය වන අතර අඳුරු අදියරට එළිය සෘජුව අවශ්‍ය නොවේ.", "තයිලකොයිඩ & ස්ට්‍රෝමාව"),
      CardContentTuple("ප්‍රභාසංස්ලේෂණයේ ආලෝක අදියරේදී සිදුවන ජලයේ ප්‍රකාශ විච්ඡේදනය යනු කුමක්ද?", "ආලෝක ශක්තිය අවශෝෂණය කරගත් ක්ලෝරොෆිල් මඟින් ජල අණු H⁺, ඉලෙක්ට්‍රෝන (e⁻) සහ O₂ බවට බිඳ හෙලීමයි (2H₂O → 4H⁺ + 4e⁻ + O₂).", "පිටවන ඔක්සිජන් වායුවේ ප්‍රභවය ජලය මිස CO₂ නොවේ.", "2H₂O → 4H⁺ + 4e⁻ + O₂"),
      CardContentTuple("ප්‍රභාසංස්ලේෂණයේ ආලෝක අදියරේදී නිපදවෙන ශක්ති ප්‍රභව 2 මොනවාද?", "ATP (ඇඩිනොසීන් ට්‍රයිපොස්ෆේට්) සහ NADPH (හෝ NADPH₂).", "මේවා අඳුරු අදියරේදී CO₂ කාබෝහයිඩ්‍රේට බවට ඔක්සිහරණය කිරීමට යොදා ගැනේ.", "ATP & NADPH"),
      CardContentTuple("ප්‍රභාසංස්ලේෂණයට බලපාන ප්‍රධාන බාහිර සාධක 4 මොනවාද?", "1. ආලෝක තීව්‍රතාව 2. කාබන් ඩයොක්සයිඩ් (CO₂) සාන්ද්‍රණය 3. උෂ්ණත්වය 4. ජල සැපයුම.", "සීමාකාරී සාධක පිළිබඳ බ්ලැක්මන්ගේ නියමය මීට අදාළ වේ.", "ආලෝකය, CO₂, උෂ්ණත්වය, ජලය"),
      CardContentTuple("සීමාකාරී සාධක පිළිබඳ බ්ලැක්මන්ගේ නියමය ප්‍රකාශ කරන්න.", "ක්‍රියාවලියක සීඝ්‍රතාවය ස්වාධීන සාධක කිහිපයක් මත රඳා පවතී නම්, එහි සීඝ්‍රතාවය පාලනය වන්නේ අවම මට්ටමක පවතින සාධකය මඟිනි.", "උදා: ආලෝකය උපරිම වුවද CO₂ අඩු නම් සීඝ්‍රතාව සීමා වේ.", "Blackman's Law of Limiting Factors"),
      CardContentTuple("ශාක පත්‍රවල අඩංගු ප්‍රධාන ප්‍රභාසංස්ලේෂක වර්ණක මොනවාද?", "ක්ලෝරොෆිල් a (නිල්-කොළ), ක්ලෝරොෆිල් b (කහ-කොළ), කැරොටිනොයිඩ් (තැඹිලි-රතු) සහ සැන්තොෆිල් (කහ).", "ප්‍රධාන වර්ණකය ක්ලෝරොෆිල් a වන අතර අනෙක්වා උපකාරක වර්ණක වේ.", "ක්ලෝරොෆිල් a, b, කැරොටින්, සැන්තොෆිල්"),
      CardContentTuple("පත්‍රයක ප්‍රභාසංස්ලේෂණය වැඩිම සීඝ්‍රතාවයකින් සිදුවන පටකය කුමක්ද? හේතුව කුමක්ද?", "පැලිසේඩ් මෘදුස්තර පටකය. එහි ඇති සෛලවල ඉතා විශාල වශයෙන් හරිතලව ඝනත්වයකින් පිහිටා තිබීම හේතුවයි.", "ඉහළ අපිචර්මයට යටින් සමීපව පිහිටා ආලෝකය උපරිමයෙන් ග්‍රහණය කරයි.", "පැලිසේඩ් පටකය"),
